1	package book
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// 本文件为日内亏损保护补充回归保障：调用方“首次开启交易日”且把亏损上限设为零时，
9	// 即使行情没有下跌、当前亏损为零，也必须立即限制买入并处理开日前已经接受的有效
10	// 买单——重点覆盖账户已有部分成交买单、其他合约挂单买单与有效卖单同时存在的情况。
11	//
12	// 关键构造：初始现金 1000；A、B 两个合约最大持仓量均为 100，最新已生效报价均为
13	// 序号 1（A：时刻 10、价格 10；B：时刻 20、价格 20）。先接受 A 买单（编号 1，
14	// 总量 10、限价 10），其中 4 份按价格 9 成交（cash=964，A 持仓 4，剩余 6 份占用
15	// 60 现金）；再接受 B 买单（编号 2，总量 3、限价 20，占用 60 现金，B 无持仓）；
16	// 最后接受 A 卖单（编号 3，数量 2、限价 9，占用 2 股可卖数量，A 可卖 2）。
17	// 此时现金 964、两张买单各占用 60 现金（合计 120），账户尚未开启交易日，账户总
18	// 持仓金额上限也未启用。
19	//
20	// 以日号 1、亏损上限 0 开日：基准净值与当前净值均为 964 现金 + A 持仓 4×10 =
21	// 1004，亏损为 0；0 >= 0 立即触线，买入限制即刻生效。先追加一条来源为“开日”的
22	// 触线记录（估值报价只包含有持仓的 A，只有挂单的 B 不得进入持仓估值），再按买单
23	// 编号从大到小撤销：先撤编号 2 的 B 买单剩余 3 份，再撤编号 1 的 A 买单剩余 6 份；
24	// 编号更大的 A 卖单继续有效。现金仍为 964、A 持仓仍为 4、A 买单累计成交仍为 4，
25	// 占用现金降为 0、可用现金变为 964，A 可卖数量仍为 2，已经入账的成交不重新计价。
26	//
27	// 边界：同样的开日前状态使用正数上限 1 时零亏损不触线，不新增触线或撤销记录，
28	// 订单与占用保持原值；负亏损上限必须报错，账户仍未开日，不撤单、不释放占用、
29	// 不新增记录。
30	
31	// startDayZeroLimitSetup 构造“首次开日且零上限”的共用前置状态，返回引擎与
32	// A 买单、B 买单、A 卖单的编号（依次为 1、2、3）。
33	func startDayZeroLimitSetup(t *testing.T) (e *Engine, buyA, buyB, sellA int64) {
34		t.Helper()
35		e, _ = NewEngine(1000)
36		mustSetMax(t, e, "A", 100)
37		mustSetMax(t, e, "B", 100)
38		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
39		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 20, Price: 20}, 1)
40	
41		buyA = mustBuy(t, e, "A", 10, 10)
42		if _, err := e.Fill(Trade{TradeID: 1, OrderID: buyA, Symbol: "A", Side: Buy, Price: 9, Qty: 4}); err != nil {
43			t.Fatal(err)
44		}
45		buyB = mustBuy(t, e, "B", 3, 20)
46		sellA = mustSell(t, e, "A", 2, 9)
47	
48		// 现金 964；A 买单剩余 6×10 与 B 买单 3×20 各占用 60；A 持仓 4，卖单占用 2。
49		if e.Cash() != 964 || e.ReservedCash() != 120 || e.AvailableCash() != 844 ||
50			e.Position("A") != 4 || e.Position("B") != 0 || e.Sellable("A") != 2 {
51			t.Fatalf("前置状态错误: cash=%d reserved=%d available=%d posA=%d posB=%d sellableA=%d",
52				e.Cash(), e.ReservedCash(), e.AvailableCash(),
53				e.Position("A"), e.Position("B"), e.Sellable("A"))
54		}
55		o, _ := e.Order(buyA)
56		if o.Status != StatusPartial || o.Qty != 10 || o.Filled != 4 || o.Remaining() != 6 {
57			t.Fatalf("A 买单应为部分成交、累计成交 4、剩余 6: %+v", o)
58		}
59		o, _ = e.Order(buyB)
60		if o.Status != StatusPending || o.Qty != 3 || o.Filled != 0 || o.Remaining() != 3 {
61			t.Fatalf("B 买单应待成交、剩余 3: %+v", o)
62		}
63		o, _ = e.Order(sellA)
64		if o.Status != StatusPending || o.Qty != 2 || o.Limit != 9 || o.Remaining() != 2 {
65			t.Fatalf("A 卖单应保持有效、占用 2 股: %+v", o)
66		}
67		return e, buyA, buyB, sellA
68	}
69	
70	// TestRiskStartDayZeroLimitRestrictsAndCancelsPendingBuys 覆盖主路径：零上限在首次
71	// 开日时立即触线（亏损为 0），先固化开日触线记录（持仓估值只含 A，不含只有挂单的
72	// B），再按买单编号从大到小撤销 B 买单与 A 买单剩余部分，卖单与已入账成交保留；
73	// 开日后新买单即使其他条件全部满足也被风险保护拒绝。
74	func TestRiskStartDayZeroLimitRestrictsAndCancelsPendingBuys(t *testing.T) {
75		e, buyA, buyB, sellA := startDayZeroLimitSetup(t)
76	
77		recsBefore := len(e.Records())
78		if err := e.StartTradingDay(1, 0); err != nil {
79			t.Fatalf("零上限合法开日必须成功: %v", err)
80		}
81	
82		// 基准净值与当前净值都是 1004：现金 964 + A 持仓 4×seq1 报价 10；买单冻结的
83		// 120 现金属于余额不重复扣除；B 只有挂单没有持仓，不贡献持仓市值。
84		st := e.RiskStatus()
85		if !st.Open || st.Day != 1 {
86			t.Fatalf("交易日应已开启: %+v", st)
87		}
88		if st.Baseline != 1004 || st.Equity != 1004 || st.Loss != 0 ||
89			st.LossLimit != 0 || !st.Restricted {
90			t.Fatalf("零上限开日应得到基准与净值 1004、亏损 0 并立即限制: %+v", st)
91		}
92	
93		// 本次开日只新增三条记录：触线、撤 B 买单、撤 A 买单（按编号从大到小）。
94		newRecs := e.Records()[recsBefore:]
95		if len(newRecs) != 3 {
96			t.Fatalf("开日应只新增 3 条记录（1 触线 + 2 撤单），实际 %d 条", len(newRecs))
97		}
98	
99		trig := newRecs[0]
100		if trig.Kind != RecordRiskTriggered {
101			t.Fatalf("第一条新增记录必须是触线记录: %+v", trig)
102		}
103		if trig.RiskTrigger != RiskTriggerStartDay || trig.RiskRefSeq != 0 || trig.RiskRefMoment != 0 {
104			t.Fatalf("触线来源必须是开日且无报价/成交关联编号: trigger=%s ref=%d moment=%d",
105				trig.RiskTrigger, trig.RiskRefSeq, trig.RiskRefMoment)
106		}
107		if trig.RiskDay != 1 || trig.RiskBaseline != 1004 || trig.RiskEquity != 1004 ||
108			trig.RiskLoss != 0 || trig.RiskLimit != 0 || !trig.RiskRestrict {
109			t.Fatalf("触线记录必须保存日号 1、净值 1004、亏损 0、上限 0 与已限制状态: %+v", trig)
110		}
111		// 估值报价只包含有持仓的 A；只有挂单的 B 不能算进持仓估值。
112		if len(trig.RiskQuoteRefs) != 1 ||
113			trig.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 1, Moment: 10, Price: 10}) {
114			t.Fatalf("触线估值报价只能包含持仓的 A@seq1(10,10)，不得包含只有挂单的 B: %+v",
115				trig.RiskQuoteRefs)
116		}
117	
118		// 先撤编号更大的 B 买单（编号 2）剩余 3 份。
119		crB := newRecs[1]
120		if crB.Kind != RecordCanceled || crB.OrderID != buyB || crB.Symbol != "B" ||
121			crB.Side != Buy || crB.Limit != 20 || crB.Qty != 3 || crB.Filled != 0 || crB.Remaining != 3 {
122			t.Fatalf("第二条记录必须是撤销 B 买单剩余 3 份: %+v", crB)
123		}
124		if !crB.QuoteValid || crB.QuoteSeq != 1 || crB.QuoteMoment != 20 || crB.QuotePrice != 20 {
125			t.Fatalf("B 撤单记录报价快照应锚定 B seq1(20,20): %+v", crB)
126		}
127		if crB.RiskDay != 1 || crB.RiskBaseline != 1004 || crB.RiskEquity != 1004 ||
128			crB.RiskLoss != 0 || crB.RiskLimit != 0 || !crB.RiskRestrict {
129			t.Fatalf("B 撤单记录必须保存开日时的风险快照（已限制）: %+v", crB)
130		}
131	
132		// 再撤编号 1 的 A 买单剩余 6 份，已成交 4 份保留。
133		crA := newRecs[2]
134		if crA.Kind != RecordCanceled || crA.OrderID != buyA || crA.Symbol != "A" ||
135			crA.Side != Buy || crA.Limit != 10 || crA.Qty != 10 || crA.Filled != 4 || crA.Remaining != 6 {
136			t.Fatalf("第三条记录必须是撤销 A 买单剩余 6 份、已成交 4 份保留: %+v", crA)
137		}
138		if !crA.QuoteValid || crA.QuoteSeq != 1 || crA.QuoteMoment != 10 || crA.QuotePrice != 10 {
139			t.Fatalf("A 撤单记录报价快照应锚定 A seq1(10,10): %+v", crA)
140		}
141		if crA.RiskDay != 1 || crA.RiskBaseline != 1004 || crA.RiskEquity != 1004 ||
142			crA.RiskLoss != 0 || crA.RiskLimit != 0 || !crA.RiskRestrict {
143			t.Fatalf("A 撤单记录必须保存开日时的风险快照（已限制）: %+v", crA)
144		}
145	
146		if countRiskRecords(e) != 1 {
147			t.Fatal("一个交易日只能有一条触线记录")
148		}
149	
150		// 两张买单均已撤销；编号更大的 A 卖单继续有效。
151		o, _ := e.Order(buyA)
152		if o.Status != StatusCanceled || o.Qty != 10 || o.Filled != 4 || o.Remaining() != 0 {
153			t.Fatalf("A 买单应已撤销、累计成交保留 4: %+v", o)
154		}
155		if !strings.Contains(o.Reason, "亏损 0") || !strings.Contains(o.Reason, "上限 0") {
156			t.Fatalf("A 买单撤单原因必须固化亏损 0 与零上限: %q", o.Reason)
157		}
158		o, _ = e.Order(buyB)
159		if o.Status != StatusCanceled || o.Qty != 3 || o.Filled != 0 || o.Remaining() != 0 {
160			t.Fatalf("B 买单应已撤销、无成交: %+v", o)
161		}
162		o, _ = e.Order(sellA)
163		if o.Status != StatusPending || o.Qty != 2 || o.Limit != 9 || o.Remaining() != 2 {
164			t.Fatalf("A 卖单不得被风险保护撤销，必须继续有效: %+v", o)
165		}
166	
167		// 现金余额、A 持仓与 A 买单累计成交不变；买单占用全部释放；卖单占用保留。
168		if e.Cash() != 964 || e.ReservedCash() != 0 || e.AvailableCash() != 964 ||
169			e.Position("A") != 4 || e.Sellable("A") != 2 {
170			t.Fatalf("撤单只释放买单占用：现金 964、持仓 4、可卖 2 不变，占用归零: "+
171				"cash=%d reserved=%d available=%d posA=%d sellableA=%d",
172				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Sellable("A"))
173		}
174	
175		// 此前的成交记录保持原值：成交价 9、数量 4、累计 4，报价快照停留在成交时的
176		// A seq1(10,10)；成交发生在开日前，不得事后补写风险快照或按现价重新计价。
177		var fillRec Record
178		for _, r := range e.Records() {
179			if r.Kind == RecordFilled && r.TradeID == 1 {
180				fillRec = r
181			}
182		}
183		if fillRec.TradeID != 1 {
184			t.Fatal("必须能找到成交编号 1 的原成交记录")
185		}
186		if fillRec.OrderID != buyA || fillRec.TradePrice != 9 || fillRec.Qty != 4 || fillRec.Filled != 4 {
187			t.Fatalf("原成交内容必须保持不重新计价: %+v", fillRec)
188		}
189		if !fillRec.QuoteValid || fillRec.QuoteSeq != 1 || fillRec.QuoteMoment != 10 || fillRec.QuotePrice != 10 {
190			t.Fatalf("原成交记录报价快照必须保留成交时的 A seq1(10,10): %+v", fillRec)
191		}
192		if fillRec.RiskDay != 0 || fillRec.RiskRestrict {
193			t.Fatalf("开日前的成交记录不得被事后补写风险快照: %+v", fillRec)
194		}
195	
196		// 开日后其他下单条件均满足的新买单仍必须因风险保护被拒绝（不生成订单、不占用）。
197		ordersBefore := len(e.Orders())
198		if _, err := e.Buy("A", 1, 10); err == nil {
199			t.Fatal("零上限开日触线后，新买单即使现金、报价与持仓限额都满足也必须拒绝")
200		} else if !strings.Contains(err.Error(), "日内亏损保护已触发") {
201			t.Fatalf("拒单原因必须来自日内亏损保护: %v", err)
202		}
203		if len(e.Orders()) != ordersBefore {
204			t.Fatal("被风险保护拒绝的买单不得生成订单")
205		}
206		rej := e.Records()[len(e.Records())-1]
207		if rej.Kind != RecordRejected || rej.Symbol != "A" || rej.RiskDay != 1 ||
208			rej.RiskEquity != 1004 || rej.RiskLoss != 0 || !rej.RiskRestrict {
209			t.Fatalf("新买单拒绝记录必须固化开日后已限制的风险快照: %+v", rej)
210		}
211		if e.Cash() != 964 || e.ReservedCash() != 0 {
212			t.Fatalf("拒绝新买单不得改动资金与占用: cash=%d reserved=%d", e.Cash(), e.ReservedCash())
