215	
216	// TestRiskStartDayPositiveLimitWithZeroLossDoesNotTrigger 覆盖正数上限边界：
217	// 同样的开日前状态以上限 1 开日，零亏损不触线，不新增触线或撤销记录，订单与
218	// 占用保持原值；保护未限制时新买单可正常接受。
219	func TestRiskStartDayPositiveLimitWithZeroLossDoesNotTrigger(t *testing.T) {
220		e, buyA, buyB, sellA := startDayZeroLimitSetup(t)
221	
222		recsBefore := len(e.Records())
223		if err := e.StartTradingDay(1, 1); err != nil {
224			t.Fatalf("正数上限合法开日必须成功: %v", err)
225		}
226		if len(e.Records()) != recsBefore {
227			t.Fatalf("零亏损开日不得新增任何记录，实际新增 %d 条", len(e.Records())-recsBefore)
228		}
229		st := e.RiskStatus()
230		if !st.Open || st.Day != 1 || st.Baseline != 1004 || st.Equity != 1004 ||
231			st.Loss != 0 || st.LossLimit != 1 || st.Restricted {
232			t.Fatalf("零亏损低于正数上限 1，不应触线: %+v", st)
233		}
234		if countRiskRecords(e) != 0 {
235			t.Fatal("零亏损正数上限开日不得产生触线记录")
236		}
237	
238		// 订单与占用保持开日前原值。
239		if o, _ := e.Order(buyA); o.Status != StatusPartial || o.Filled != 4 || o.Remaining() != 6 {
240			t.Fatalf("A 买单必须保持部分成交、剩余 6: %+v", o)
241		}
242		if o, _ := e.Order(buyB); o.Status != StatusPending || o.Remaining() != 3 {
243			t.Fatalf("B 买单必须保持待成交、剩余 3: %+v", o)
244		}
245		if o, _ := e.Order(sellA); o.Status != StatusPending || o.Remaining() != 2 {
246			t.Fatalf("A 卖单必须保持有效: %+v", o)
247		}
248		if e.Cash() != 964 || e.ReservedCash() != 120 || e.AvailableCash() != 844 ||
249			e.Position("A") != 4 || e.Sellable("A") != 2 {
250			t.Fatalf("开日不得改动资金、占用、持仓与可卖数量: cash=%d reserved=%d available=%d posA=%d sellableA=%d",
251				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Sellable("A"))
252		}
253	
254		// 保护未限制：其他条件满足的新买单可以接受。
255		mustBuy(t, e, "A", 1, 10)
256	}
257	
258	// TestRiskStartDayNegativeLimitRejectedWithoutSideEffects 覆盖负上限边界：负亏损
259	// 上限必须报错，账户仍未开日，不撤单、不释放占用、不新增记录。
260	func TestRiskStartDayNegativeLimitRejectedWithoutSideEffects(t *testing.T) {
261		e, buyA, buyB, sellA := startDayZeroLimitSetup(t)
262	
263		recsBefore := len(e.Records())
264		if err := e.StartTradingDay(1, -1); err == nil {
265			t.Fatal("负亏损上限开日必须返回错误")
266		} else if !strings.Contains(err.Error(), "亏损上限不能为负") {
267			t.Fatalf("错误原因必须指向负亏损上限: %v", err)
268		}
269		if len(e.Records()) != recsBefore {
270			t.Fatalf("非法开日不得新增记录，实际新增 %d 条", len(e.Records())-recsBefore)
271		}
272		if e.RiskStatus().Open {
273			t.Fatal("负上限开日失败后账户必须仍未开日")
274		}
275		if countRiskRecords(e) != 0 {
276			t.Fatal("负上限开日失败不得产生触线记录")
277		}
278	
279		// 不撤单、不释放占用：两张买单与卖单保持有效，资金占用原样保留。
280		if o, _ := e.Order(buyA); o.Status != StatusPartial || o.Filled != 4 || o.Remaining() != 6 {
281			t.Fatalf("非法开日不得改动 A 买单: %+v", o)
282		}
283		if o, _ := e.Order(buyB); o.Status != StatusPending || o.Remaining() != 3 {
284			t.Fatalf("非法开日不得改动 B 买单: %+v", o)
285		}
286		if o, _ := e.Order(sellA); o.Status != StatusPending || o.Remaining() != 2 {
287			t.Fatalf("非法开日不得改动 A 卖单: %+v", o)
288		}
289		if e.Cash() != 964 || e.ReservedCash() != 120 || e.AvailableCash() != 844 ||
290			e.Position("A") != 4 || e.Sellable("A") != 2 {
291			t.Fatalf("非法开日不得改动资金、占用、持仓与可卖数量: cash=%d reserved=%d available=%d posA=%d sellableA=%d",
292				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Sellable("A"))
293		}
294	
295		// 修正为零上限后仍应按主路径立即触线撤单。
296		if err := e.StartTradingDay(1, 0); err != nil {
297			t.Fatalf("非法尝试后合法零上限开日必须成功: %v", err)
298		}
299		st := e.RiskStatus()
300		if !st.Open || !st.Restricted || st.Baseline != 1004 || st.Equity != 1004 || st.Loss != 0 {
301			t.Fatalf("非法尝试后零上限开日仍应立即触线: %+v", st)
302		}
303		if o, _ := e.Order(buyA); o.Status != StatusCanceled || o.Filled != 4 || o.Remaining() != 0 {
304			t.Fatalf("A 买单剩余 6 份必须被保护撤销、已成交 4 份保留: %+v", o)
305		}
306		if o, _ := e.Order(buyB); o.Status != StatusCanceled || o.Remaining() != 0 {
307			t.Fatalf("B 买单必须被保护撤销: %+v", o)
308		}
309		if o, _ := e.Order(sellA); o.Status != StatusPending || o.Remaining() != 2 {
310			t.Fatalf("A 卖单必须继续有效: %+v", o)
311		}
312		if e.Cash() != 964 || e.ReservedCash() != 0 || e.AvailableCash() != 964 ||
313			e.Position("A") != 4 || e.Sellable("A") != 2 {
314			t.Fatalf("触线撤单只释放买单占用: cash=%d reserved=%d available=%d posA=%d sellableA=%d",
315				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Sellable("A"))
316		}
317		if countRiskRecords(e) != 1 {
318			t.Fatal("非法尝试不得占用触线记录，合法交易日只能有一条触线记录")
319		}
320	}
321

